import psycopg2
import os
import hashlib
import time
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'inventory')
DB_USER = os.environ.get('DB_USER', 'app_user')
DB_PASS = os.environ.get('DB_PASS', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=DB_HOST, database=DB_NAME,
            user=DB_USER, password=DB_PASS
        )
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key')
        if not api_key:
            return jsonify({'error': 'Missing API key'}), 401
        # Timing-safe comparison against stored hash
        key_hash = hashlib.sha256(api_key.encode()).hexdigest()
        expected = os.environ.get('API_KEY_HASH', '')
        if not hmac_compare(key_hash, expected):
            return jsonify({'error': 'Invalid API key'}), 403
        return f(*args, **kwargs)
    return decorated

def hmac_compare(a, b):
    if len(a) != len(b):
        return False
    result = 0
    for x, y in zip(a, b):
        result |= ord(x) ^ ord(y)
    return result == 0

@app.route('/api/v2/inventory/lookup', methods=['GET'])
@require_api_key
def inventory_lookup():
    """Look up inventory items by various criteria."""
    sku = request.args.get('sku', '')
    warehouse = request.args.get('warehouse', '')

    if not sku and not warehouse:
        return jsonify({'error': 'Provide sku or warehouse parameter'}), 400

    conn = get_db()
    cur = conn.cursor()

    # Build query based on provided parameters
    conditions = []
    if sku:
        conditions.append(f"sku = '{sku}'")
    if warehouse:
        conditions.append(f"warehouse_code = '{warehouse}'")

    where_clause = ' AND '.join(conditions)
    query = f"SELECT sku, product_name, quantity, warehouse_code, last_updated FROM inventory WHERE {where_clause}"

    try:
        cur.execute(query)
        rows = cur.fetchall()
        results = []
        for row in rows:
            results.append({
                'sku': row[0],
                'product_name': row[1],
                'quantity': row[2],
                'warehouse': row[3],
                'last_updated': str(row[4])
            })
        return jsonify({'items': results, 'count': len(results)})
    except Exception as e:
        conn.rollback()
        app.logger.error(f"Query error: {e}")
        return jsonify({'error': 'Database error'}), 500

@app.route('/api/v2/inventory/update', methods=['POST'])
@require_api_key
def inventory_update():
    """Update inventory quantity - uses parameterized queries."""
    data = request.get_json()
    if not data or 'sku' not in data or 'quantity' not in data:
        return jsonify({'error': 'Missing required fields'}), 400

    conn = get_db()
    cur = conn.cursor()
    cur.execute(
        "UPDATE inventory SET quantity = %s, last_updated = NOW() WHERE sku = %s",
        (data['quantity'], data['sku'])
    )
    conn.commit()
    return jsonify({'status': 'updated', 'sku': data['sku']})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'timestamp': time.time()})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
